mapper.sql:
SELECT
    o.buyer_id                                                AS user_id,
    MAX(o.buyer_name)                                         AS user_name,
    MAX(o.buyer_phone)                                        AS phone,
    COALESCE(SUM(CASE WHEN o.create_time >= #{todayStart} AND o.create_time <= #{todayEnd}
                      THEN o.total_amount ELSE 0 END), 0)     AS today_purchase_amount,
    COALESCE(SUM(CASE WHEN o.create_time >= #{todayStart} AND o.create_time <= #{todayEnd}
                      THEN o.recommend_amount ELSE 0 END), 0) AS today_share_amount,
    COALESCE(SUM(CASE WHEN o.create_time >= #{todayStart} AND o.create_time <= #{todayEnd}
                       AND l.operate_type = 1
                      THEN l.payment_amount ELSE 0 END), 0)   AS today_payment_amount,
    COALESCE(SUM(CASE WHEN o.create_time >= #{todayStart} AND o.create_time <= #{todayEnd}
                       AND l.operate_type = 1
                      THEN l.receipt_amount ELSE 0 END), 0)   AS today_receipt_amount,
    COALESCE(SUM(CASE WHEN o.create_time >= #{yesterdayStart} AND o.create_time <= #{yesterdayEnd}
                      THEN o.total_amount ELSE 0 END), 0)     AS yesterday_purchase_amount,
    COALESCE(SUM(CASE WHEN o.create_time >= #{yesterdayStart} AND o.create_time <= #{yesterdayEnd}
                      THEN o.recommend_amount ELSE 0 END), 0) AS yesterday_share_amount,
    COALESCE(SUM(CASE WHEN o.create_time >= #{yesterdayStart} AND o.create_time <= #{yesterdayEnd}
                       AND l.operate_type = 1
                      THEN l.payment_amount ELSE 0 END), 0)   AS yesterday_payment_amount,
    COALESCE(SUM(CASE WHEN o.create_time >= #{yesterdayStart} AND o.create_time <= #{yesterdayEnd}
                       AND l.operate_type = 1
                      THEN l.receipt_amount ELSE 0 END), 0)   AS yesterday_receipt_amount
FROM t_rob_order o
LEFT JOIN t_rob_order_operate_log l
    ON l.order_id = o.id AND l.operate_type = 1
WHERE o.is_deleted = 0
  AND o.order_status = 1
  AND o.create_time >= #{yesterdayStart}
  AND o.create_time <= #{todayEnd}

GROUP BY o.buyer_id, o.buyer_name, o.buyer_phone
ORDER BY o.buyer_id DESC
